module workbench {

    /**
     * "Add to graph": the Workbench pages queue resources, statements and queries for the Graph page of the same
     * repository. The queue is a JSON array in localStorage under rdf4j-workbench-graph-additions:<basePath>|<id>;
     * the Graph page (src/main/frontend/graph-explorer/graph-additions.ts) takes it when it opens or when another tab
     * changes it. Terms are N-Triples terms (workbench.queryStream.ntriplesTerm).
     */
    export module graphAdditions {

        export interface GraphContext {
            basePath?: string;
            repositoryId?: string | null;
        }

        export interface GraphAddition {
            kind: string;
            term?: string;
            subject?: string;
            predicate?: string;
            object?: string;
            query?: string;
        }

        interface QueueStorage {
            getItem(key: string): string | null;
            setItem(key: string, value: string): void;
        }

        export var STORAGE_PREFIX = 'rdf4j-workbench-graph-additions:';
        var LIMIT = 500;
        var TERM = /^(<[^<>"{}|^`\\\s]*>|_:\S+|".*"(@[A-Za-z0-9-]+|\^\^<[^<>\s]*>)?|<<\(.*\)>>)$/;

        function scopeOf(context: GraphContext): string {
            return String(context.basePath || '').replace(/\/+$/, '') + '|' + String(context.repositoryId || '');
        }

        /** The localStorage key of a repository's queue. */
        export function storageKey(context: GraphContext): string {
            return STORAGE_PREFIX + scopeOf(context);
        }

        function defaultStorage(): QueueStorage | null {
            try {
                return typeof localStorage !== 'undefined' ? localStorage : null;
            } catch (e) {
                return null;
            }
        }

        function valid(entry: any): entry is GraphAddition {
            if (!entry || typeof entry !== 'object') {
                return false;
            }
            if (entry.kind === 'resource') {
                return typeof entry.term === 'string' && TERM.test(entry.term);
            }
            if (entry.kind === 'statement') {
                return [entry.subject, entry.predicate, entry.object].every((term: any) =>
                    typeof term === 'string' && TERM.test(term));
            }
            if (entry.kind === 'query') {
                return typeof entry.query === 'string' && entry.query.trim().length > 0 && entry.query.length <= 150000;
            }
            return false;
        }

        function identity(entry: GraphAddition): string {
            return JSON.stringify([entry.kind, entry.term, entry.subject, entry.predicate, entry.object, entry.query]);
        }

        function only(entry: GraphAddition): GraphAddition {
            if (entry.kind === 'resource') {
                return { kind: 'resource', term: entry.term };
            }
            if (entry.kind === 'statement') {
                return { kind: 'statement', subject: entry.subject, predicate: entry.predicate, object: entry.object };
            }
            return { kind: 'query', query: entry.query };
        }

        /** The additions queued for the repository's Graph page, oldest first. */
        export function pending(context: GraphContext, storage?: QueueStorage | null): GraphAddition[] {
            var store = storage === undefined ? defaultStorage() : storage;
            if (!store || !context || !context.repositoryId) {
                return [];
            }
            try {
                var parsed = JSON.parse(store.getItem(storageKey(context)) || '[]');
                return Array.isArray(parsed) ? parsed.filter(valid).map(only) : [];
            } catch (e) {
                return [];
            }
        }

        /**
         * Queues one or more additions (duplicates once, the newest 500 kept) and returns how many are waiting; 0 when
         * nothing could be queued (no repository, invalid entries, or storage that cannot be written).
         */
        export function add(context: GraphContext, entries: GraphAddition | GraphAddition[],
                            storage?: QueueStorage | null): number {
            var store = storage === undefined ? defaultStorage() : storage;
            var adding = (Array.isArray(entries) ? entries : [entries]).filter(valid).map(only);
            if (!store || !context || !context.repositoryId || !adding.length) {
                return 0;
            }
            try {
                var queue = pending(context, store);
                var seen: { [key: string]: boolean } = {};
                queue.concat(adding).forEach((entry: GraphAddition) => {
                    seen[identity(entry)] = false;
                });
                var merged = queue.concat(adding).filter((entry: GraphAddition) => {
                    var key = identity(entry);
                    if (seen[key]) {
                        return false;
                    }
                    seen[key] = true;
                    return true;
                }).slice(-LIMIT);
                store.setItem(storageKey(context), JSON.stringify(merged));
                return merged.length;
            } catch (e) {
                return 0;
            }
        }

        /** The repository's Graph page. */
        export function graphUrl(context: GraphContext): string {
            return String(context.basePath || '').replace(/\/+$/, '') + '/repositories/'
                + encodeURIComponent(String(context.repositoryId || '')) + '/graph';
        }
    }
}

declare var module: any;

if (typeof module !== 'undefined' && module.exports) {
    module.exports = workbench.graphAdditions;
}
